/**
 * Vendors the ext-apps browser bundle into lib/extAppsBundle.js as an ES module
 * exporting a string.
 *
 * Why vendor it rather than read node_modules at runtime: the widget HTML must
 * inline this script (the iframe CSP blocks CDN fetches), and a runtime fs read
 * of a dynamically-resolved node_modules path is not reliably traced into a
 * Vercel serverless bundle. A plain `import` always is.
 *
 * Run after upgrading @modelcontextprotocol/ext-apps:
 *   node scripts/build-ext-apps-bundle.mjs
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);

const src = readFileSync(
  require.resolve('@modelcontextprotocol/ext-apps/app-with-deps'),
  'utf8'
);

// The bundle ends in `export{A as App,...}`. Rewrite that into a global so the
// inlined <script> works without module resolution inside the iframe.
const globalised = src.replace(/export\s*\{([^}]+)\};?\s*$/, (_, body) =>
  'globalThis.ExtApps={' +
  body
    .split(',')
    .map((pair) => {
      const [local, exported] = pair.split(/\s+as\s+/).map((s) => s.trim());
      return `${exported ?? local}:${local}`;
    })
    .join(',') +
  '};'
);

if (globalised === src) {
  console.error('ERROR: export{...} footer not found — bundle format changed.');
  process.exit(1);
}

const out = resolve(here, '../lib/extAppsBundle.js');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  '// GENERATED by scripts/build-ext-apps-bundle.mjs — do not edit by hand.\n' +
    'export default ' +
    JSON.stringify(globalised) +
    ';\n',
  'utf8'
);

console.log(`wrote ${out} (${globalised.length} chars)`);
